module TopModule (
  input  logic clk,
  input  logic reset,
  input  logic j,
  input  logic k,
  output logic out
);
  typedef enum logic {OFF=1'b0, ON=1'b1} state_t;
  state_t state, next_state;

  always_ff @(posedge clk) begin
    if (reset)
      state <= OFF;
    else
      state <= next_state;
